export const CUES = [{"id": 1, "chapter": "ch1", "text": "当知识库同时使用关键词检索和向量检索时，两路各自返回了一份排名，怎么把它们合并成一份最终榜单？", "startSec": 0.0, "durationSec": 6.415166666666667, "startFrame": 0, "durationFrames": 192, "startSample": 0, "durationSamples": 153964}, {"id": 2, "chapter": "ch1", "text": "直接把原始分数相加是行不通的。向量检索的分数通常在 0 到 1 之间，而关键词检索的分数没有固定上限，直接相加会让总分被关键词检索主导。", "startSec": 6.415166666666667, "durationSec": 9.49075, "startFrame": 192, "durationFrames": 285, "startSample": 153964, "durationSamples": 227778}, {"id": 3, "chapter": "ch1", "text": "解决办法是 RRF，全称 Reciprocal Rank Fusion，中文叫倒数排名融合。", "startSec": 15.905916666666666, "durationSec": 4.760291666666666, "startFrame": 477, "durationFrames": 143, "startSample": 381742, "durationSamples": 114247}, {"id": 4, "chapter": "ch1", "text": "它不看原始分数，只看名次。一篇文档在某一路排第 rank 名，名次从 1 开始算，就拿到 1 除以 k 加 rank 的分数，常数 k 通常取 60；如果这一路没有命中，就记 0 分。", "startSec": 20.666208333333334, "durationSec": 11.673416666666666, "startFrame": 620, "durationFrames": 350, "startSample": 495989, "durationSamples": 280162}, {"id": 5, "chapter": "ch1", "text": "来看一组示例排名。关键词检索的前三名是文档 A、文档 B、文档 C；向量检索的前两名是文档 B、文档 C，文档 A 没有命中。", "startSec": 32.339625, "durationSec": 9.095875, "startFrame": 970, "durationFrames": 273, "startSample": 776151, "durationSamples": 218301}, {"id": 6, "chapter": "ch1", "text": "文档 A 只在关键词检索排第 1 名，得分是 1 除以 61 加 0，约为 0.0164。", "startSec": 41.4355, "durationSec": 5.692166666666667, "startFrame": 1243, "durationFrames": 171, "startSample": 994452, "durationSamples": 136612}, {"id": 7, "chapter": "ch1", "text": "文档 B 在两路分别排第 2 名和第 1 名，得分是 1 除以 62 加 1 除以 61，约为 0.0325。文档 C 两路相加约为 0.0320。", "startSec": 47.12766666666667, "durationSec": 8.594875, "startFrame": 1414, "durationFrames": 258, "startSample": 1131064, "durationSamples": 206277}, {"id": 8, "chapter": "ch1", "text": "最终，被两路共同认可的文档 B 和文档 C 升到前两名，单路第一的文档 A 退到第 3 名。不过 RRF 只看名次、不读正文内容，通常用来做多路检索的快速粗排。", "startSec": 55.722541666666665, "durationSec": 10.407625, "startFrame": 1672, "durationFrames": 312, "startSample": 1337341, "durationSamples": 249783}];
